--USE ieee.numeric_std.ALL;

ENTITY tb_frequency_meter IS
END tb_frequency_meter;

ARCHITECTURE behavior OF tb_frequency_meter IS 

-- Component Declaration for the Unit Under Test (UUT)
constant fclk : integer := 100;
constant fxmax : integer := 150;

COMPONENT frequency_meter
generic (
fclk : integer := fclk;
fxmax : integer := fxmax
);
PORT(
clk : IN  std_logic;
x : IN  std_logic;
test : OUT  std_logic;
fx : OUT  integer range 0 to fxmax
);
END COMPONENT;


--Inputs
signal clk : std_logic := '0';
signal x : std_logic := '0';

--Outputs
signal test : std_logic;
signal fx : integer range 0 to fxmax;

-- Clock period definitions
constant clk_period : time := 5.5 ns;
constant clk_period1 : time := 10 ns;

BEGIN

-- Instantiate the Unit Under Test (UUT)
uut: frequency_meter PORT MAP (
clk => clk,
x => x,
test => test,
fx => fx
);

-- Clock process definitions
